static const char art3m1s_rule_cg[] = "// art3m1s GXM rule transition fragment shader.\n// Input matches Borealis' NanoVG fill vertex shader. This shader returns\n// premultiplied RGBA for ONE / ONE_MINUS_SRC_ALPHA blending.\n// Not wired into production until a compiled GXP and per-call mask binding exist.\nuniform float4 frag[11];\n\n#define scissorMat float3x3(frag[0].xyz, frag[1].xyz, frag[2].xyz)\n#define paintMat float3x3(frag[3].xyz, frag[4].xyz, frag[5].xyz)\n#define innerCol frag[6]\n#define scissorExt frag[8].xy\n#define scissorScale frag[8].zw\n#define extent frag[9].xy\n// These slots are unused by the ordinary image fill shader.\n#define progress frag[9].z\n#define vague frag[9].w\n\nfloat4 main(\n    uniform sampler2D oldFrame : TEXUNIT0,\n    uniform sampler2D ruleMap : TEXUNIT1,\n    float2 ftcoord : TEXCOORD0,\n    float2 fpos : TEXCOORD1\n) : COLOR {\n    float2 uv = mul(paintMat, float3(fpos, 1.0)).xy / extent;\n    float4 color = tex2D(oldFrame, uv);\n    float rule = tex2D(ruleMap, uv).r;\n    float v = max(vague, 1.0 / 255.0);\n    float t = progress * (1.0 + v) - v;\n    float keep = smoothstep(t, t + v, rule);\n    float2 sc = abs(mul(scissorMat, float3(fpos, 1.0)).xy) - scissorExt;\n    sc = saturate(float2(0.5, 0.5) - sc * scissorScale);\n    color.rgb *= color.a;\n    return color * innerCol * keep * sc.x * sc.y;\n}\n";